static HANDLE metadata=INVALID_HANDLE_VALUE;static std::wstring target,original;static BY_HANDLE_FILE_INFORMATION sourceId={};static bool inserted=false,observed=false,declined=false;
void Before(const wchar_t*directory){if(inserted)return;inserted=true;original=directory;metadata=CreateFileW(directory,FILE_WRITE_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,NULL,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,NULL);C(metadata!=INVALID_HANDLE_VALUE&&GetFileInformationByHandle(metadata,&sourceId),"retain source directory identity before actual retarget race");Mount mount=Reparse(target);C(SetReparse(metadata,mount),"insert actual metadata-only reparse retarget between guard and NT file creation");}
void After(const wchar_t*directory,const wchar_t*leaf,HANDLE file){if(observed)return;observed=true;C(ClearReparse(metadata),"restore only owned source-directory reparse metadata after race");CloseHandle(metadata);metadata=INVALID_HANDLE_VALUE;
 BY_HANDLE_FILE_INFORMATION current={},created={},byPath={};HANDLE source=CreateFileW(directory,FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,NULL,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,NULL);C(source!=INVALID_HANDLE_VALUE&&GetFileInformationByHandle(source,&current),"source directory identity after race");CloseHandle(source);C(sourceId.dwVolumeSerialNumber==current.dwVolumeSerialNumber&&sourceId.nFileIndexHigh==current.nFileIndexHigh&&sourceId.nFileIndexLow==current.nFileIndexLow,"retarget cannot replace retained source directory object");
 if(file==INVALID_HANDLE_VALUE){declined=true;C(GetFileAttributesW((std::wstring(directory)+L"\\"+leaf).c_str())==INVALID_FILE_ATTRIBUTES&&GetFileAttributesW((target+L"\\"+leaf).c_str())==INVALID_FILE_ATTRIBUTES,"relative create safely refuses changed directory without source or target file");return;}
 C(GetFileInformationByHandle(file,&created)!=FALSE,"relative FILE_CREATE returns original-source file handle");HANDLE check=CreateFileW((std::wstring(directory)+L"\\"+leaf).c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,NULL,OPEN_EXISTING,0,NULL);C(check!=INVALID_HANDLE_VALUE&&GetFileInformationByHandle(check,&byPath),"file exists in original source directory after restoring namespace");CloseHandle(check);C(created.dwVolumeSerialNumber==byPath.dwVolumeSerialNumber&&created.nFileIndexHigh==byPath.nFileIndexHigh&&created.nFileIndexLow==byPath.nFileIndexLow,"new handle file ID equals original-directory entry");C(GetFileAttributesW((target+L"\\"+leaf).c_str())==INVALID_FILE_ATTRIBUTES,"retarget target directory receives NO created file");}
